for(const id of shellIds) await place(id);

// inspect button, textfield, statusbar
async function info(id){
  const n = await figma.getNodeByIdAsync(id);
  const target = n.type==="INSTANCE" ? n.masterComponent : n;
  const desc = { name: target.name, w: target.width, h: target.height, fills: target.fills, radius: target.cornerRadius, strokes: target.strokes, strokeWeight: target.strokeWeight, children: [] };
