    const d = { t: ch.type, name: ch.name, x: ch.x, y: ch.y, w: ch.width, h: ch.height, fills: ch.fills, strokes: ch.strokes, radius: ch.cornerRadius };
    if(ch.type === "TEXT"){ d.font = JSON.stringify(ch.fontName); d.size = ch.fontSize; d.chars = ch.characters; d.ls = JSON.stringify(ch.letterSpacing); d.align = ch.textAlignHorizontal; }
    desc.children.push(d);
  }
  return desc;
}
const infos = [];
for(const id of ["6:25","6:28","6:32","6:42"]) infos.push(await info(id));
console.log("CLONES: " + out.join(" | "));
console.log("INFO: " + JSON.stringify(infos));
