function T(p,chars,fam,st,size,hx,x,y,o={}){const t=figma.createText();t.fontName={family:fam,style:st};t.fontSize=size;t.characters=chars;t.fills=[S(hx,o.o||1)];if(o.w!==undefined){t.textAutoResize="NONE";t.resize(o.w,o.h||size*1.4);}if(o.al)t.textAlignHorizontal=o.al;p.appendChild(t);t.x=x;t.y=y;if(o.n)t.name=o.n;return t;}
function setTxt(inst,nm,chars){const n=inst.findOne(x=>x.name===nm);n.characters=chars;return n;}
async function swap(inst,nm,target){const n=inst.findOne(x=>x.name===nm);await n.swapComponent(comp(target));return n;}

