function fs(f){try{if(f===undefined)return"U";if(f===null)return"N";if(f==="mixed")return"MIX";if(!Array.isArray(f))return String(f);return f.map(p=>{if(p.type==="SOLID"){const c=p.color;return"S("+Math.round(c.r*255)+","+Math.round(c.g*255)+","+Math.round(c.b*255)+")";}if(p.type==="IMAGE")return"IMG";return p.type;}).join("|");}catch(e){return"E";}}
function walk(n,d,o){if(d>3||o.length>70)return;try{o.push(d+" "+n.type+" "+String(n.name).slice(0,16)+" "+Math.round(n.width)+"x"+Math.round(n.height)+" f:"+fs(n.fills)+" s:"+fs(n.strokes)+" sw:"+(n.strokeWeight!==undefined?Math.round(n.strokeWeight*10)/10:"-")+" e:"+(n.effects?n.effects.length:"-"));}catch(e){o.push(d+" ERR "+String(e.message).slice(0,60));}if("children"in n){for(const c of n.children)walk(c,d+1,o);}}
const targets={"12:22":["backBtn"],"13:2":["contactsBtn","notifBtn","menuBtn"],"14:2":["menuBtn","contactsBtn","notifBtn"],"15:2":["menuBtn","contactsBtn","notifBtn"],"17:26":["scanBtn","notifBtn"],"18:453":["filterBtn"],"20:56":["filterBtn","calcBtn"],"24:2":["pill"]};
