function firstVec(n){if(n.type==="VECTOR")return n;if(n.children){for(let i=0;i<n.children.length;i++){const r=firstVec(n.children[i]);if(r)return r;}}return null;}
const BLUE=[{type:"SOLID",color:{r:21/255,g:115/255,b:254/255}}];
const ICONS=new Set(["icon","mi","pi","ch","chev","editIcn","pairChev"]);
const frameIds=["12:2","12:22","13:2","14:2","15:2","17:2","17:26","18:453","20:56","24:2"];
const byName={};const notes=[];let cleared=0,blued=0;
for(const fid of frameIds){const fr=await figma.getNodeByIdAsync(fid);if(!fr)continue;let insts=[];try{insts=fr.findAll(x=>x.type==="INSTANCE");}catch(e){notes.push("FE"+fid);continue;}
for(const ic of insts){try{if(ic.width>40||ic.height>40)continue;const nm=String(ic.name);const key=JSON.stringify(nm);byName[key]=(byName[key]||0)+1;
const isRow=ic.parent&&/^b?row\d/.test(String(ic.parent.name));
if(ICONS.has(nm.trim())){const had=Array.isArray(ic.fills)&&ic.fills.length>0;if(had){ic.fills=[];cleared++;}
const v=firstVec(ic);
if(isRow){if(v){v.fills=BLUE;blued++;}else notes.push("NOVEC-row "+fid);}
else if(!v)notes.push("NOVEC "+fid+" "+nm.trim());
else if(!Array.isArray(v.fills)||v.fills.length===0)notes.push("EMPTYVEC "+fid+" "+nm.trim()+"@"+Math.round(ic.absoluteTransform[0][2])%500);}
}catch(e){notes.push("E "+String(e.message).slice(0,40));}}}
return JSON.stringify({cleared,blued,byName,notes:notes.slice(0,40)}).slice(0,8000);

function firstVec(n){if(n.type==="VECTOR")return n;if(n.children){for(let i=0;i<n.children.length;i++){const r=firstVec(n.children[i]);if(r)return r;}}return null;}
const BLUE=[{type:"SOLID",color:{r:21/255,g:115/255,b:254/255}}];
const ICONS=new Set(["icon","mi","pi","ch","chev","editIcn","pairChev"]);
const frameIds=["12:2","12:22","13:2","14:2","15:2","17:2","17:26","18:453","20:56","24:2"];
let cleared=0,blued=0;const skip=[],notes=[];
function collect(n,out){try{if(n.type==="INSTANCE")out.push(n);}catch(e){}if(n.children){for(let i=0;i<n.children.length;i++){try{collect(n.children[i],out);}catch(e){}}}}
for(const fid of frameIds){const fr=await figma.getNodeByIdAsync(fid);if(!fr)continue;const insts=[];collect(fr,insts);
for(const ic of insts){try{const w=ic.width,h=ic.height;if(w>40||h>40)continue;const nm=String(ic.name).trim();const f=ic.fills;const hasF=Array.isArray(f)&&f.length>0;
const isRow=ic.parent&&/^b?row\d/.test(String(ic.parent.name));
if(ICONS.has(nm)){if(hasF){ic.fills=[];cleared++;}const v=firstVec(ic);if(isRow){if(v){v.fills=BLUE;blued++;}}else if(!v)notes.push("NOVEC "+fid+" "+nm);else if(!Array.isArray(v.fills)||v.fills.length===0)notes.push("EMPTYVEC "+fid+" "+nm);}
else if(hasF)skip.push(fid+" "+nm+" "+Math.round(w)+"x"+Math.round(h));
}catch(e){notes.push("E"+String(e.message).slice(0,30));}}}
return JSON.stringify({cleared,blued,skip:skip.slice(0,50),notes:notes.slice(0,30)}).slice(0,9000);

const frameIds=["12:2","12:22","13:2","14:2","15:2","17:2","17:26","18:453","20:56","24:2"];
function collect(n,out){try{if(Array.isArray(n.reactions)&&n.reactions.length>0){for(const r of n.reactions){const a=r.actions&&r.actions[0];if(a&&a.destinationId)out.push(n.name+"->"+a.destinationId);}}}catch(e){}if(n.children){for(let i=0;i<n.children.length;i++){try{collect(n.children[i],out);}catch(e){}}}}
const links=[];const missing=[];
for(const fid of frameIds){const fr=await figma.getNodeByIdAsync(fid);if(!fr){missing.push(fid);continue;}collect(fr,links);}
const page=await figma.getNodeByIdAsync("8:2");
return JSON.stringify({pageName:page.name,linkCount:links.length,links:links.slice(0,25),missing}).slice(0,6000);
